#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
enum OrderEvent {
    OrderPlaced { order_id: String, occurred_at: DateTime<Utc> },
    AddressChanged { customer_id: String },
}

let (tx, _rx) = tokio::sync::broadcast::channel(1024);
tx.send(OrderEvent::OrderPlaced { order_id: "42".into(), occurred_at: Utc::now() })?;
while let Ok(ev) = rx.recv().await {          // every receiver sees every event
    if let OrderEvent::OrderPlaced { order_id, .. } = ev { index.upsert(order_id); }
}
